def _backfill() -> None:
    """Existing members: the mobile they sign in with, and a family account for each parent
    recorded on a member (one guardian per parent mobile, shared by siblings)."""
    bind = op.get_bind()
    rows = bind.execute(
        sa.text("SELECT id, phone, guardian_name, guardian_phone FROM members")
    ).all()
    guardians: dict[str, int] = {}
    for member_id, phone, guardian_name, guardian_phone in rows:
        mobile = try_normalize(phone)
        if mobile:
            bind.execute(
                sa.text("UPDATE members SET portal_mobile = :m WHERE id = :id"),
                {"m": mobile, "id": member_id},
            )
        parent = try_normalize(guardian_phone)
        if not (guardian_name and parent):
            continue
        if parent not in guardians:
            result = bind.execute(
                sa.text("INSERT INTO guardians (full_name, mobile) VALUES (:n, :m)"),
                {"n": guardian_name[:150], "m": parent},
            )
            guardians[parent] = result.lastrowid
        bind.execute(
            sa.text(
                "INSERT INTO guardian_members (guardian_id, member_id, relationship, is_primary)"
                " VALUES (:g, :mem, 'guardian', 1)"
            ),
            {"g": guardians[parent], "mem": member_id},
        )


